<script setup lang="ts">
import {
  IonContent,
  IonPage,
  onIonViewWillEnter,
  useIonRouter,
} from '@ionic/vue'
import { useRoute } from 'vue-router'
import { ref, watch } from 'vue'
import { userService } from '@/services/user'
import type { FollowUserModel } from '@/types/user'
import MyAvatar from '@/components/MyAvatar.vue'
import { useToastStore } from '@/store/toast'
import CommonButton from '@/components/CommonButton.vue'
import HeaderWithReturn from '@/components/HeaderWithReturn.vue'

const router = useRoute()
const ionRouter = useIonRouter()
// get if the page should fetch follower or following
const isFollower = router.query.isFollower === 'true'
const userId = ref(router.query.userId as string)
const toastStore = useToastStore()

const userList = ref<FollowUserModel[]>([])

onIonViewWillEnter(() => {
  fetchUserList()
})

watch(
  () => router.query.userId,
  (newUserId) => {
    userId.value = newUserId as string
    fetchUserList()
  },
)

function fetchUserList() {
  if (isFollower) {
    fetchFollower()
  }
  else {
    fetchFollowing()
  }
}

async function fetchFollower() {
  // fetch follower

  try {
    const users = (await userService.getFollower(userId.value)).data
    userList.value = users
  }
  catch (error) {
    console.error(error)
  }
}

async function fetchFollowing() {
  // fetch following
  try {
    const users = (await userService.getFollowing(userId.value)).data
    userList.value = users
  }
  catch (error) {
    console.error(error)
  }
}

async function followOperation(userId: number, isFollow: boolean) {
  try {
    await userService.followOperations(
      userId,
      isFollow ? 'follow' : 'unfollow',
    )

    toastStore.setToast(
      isFollow ? 'Follow successfully' : 'Unfollow successfully',
    )
    fetchUserList()
  }
  catch (error) {
    console.error(error)
  }
}
</script>

<template>
  <ion-page>
    <header-with-return :title="isFollower ? 'Followers' : 'Followings'" />
    <ion-content>
      <div
        v-for="user in userList"
        :key="user.userId"
        class="flex items-center gap-3 px-4 py-3"
        @click="
          () => {
            ionRouter.push(`/profile?userId=${user.userId}`);
          }
        "
      >
        <my-avatar :user-name="user.userName" :src="user.avatarUrl" />
        <p class="flex-1">
          {{ user.userName }}
        </p>
        <!-- If the page is follower page -->
        <!-- the button will be following or follow back -->
        <!-- If the page is following page -->
        <!-- the button will be following only -->
        <!-- the following button will be bg-secondary -->
        <!-- the follow back button will be bg-primary -->
        <common-button
          :text="
            isFollower
              ? user.followEachOther === 0
                ? 'Follow Back'
                : 'Following'
              : 'Following'
          "
          :bg-color="user.followEachOther === 0 ? 'bg-#00F4FF' : 'bg-secondary'"
          :text-color="
            user.followEachOther === 0 ? 'text-on-primary' : 'text-on-secondary'
          "
          @click="
            () => {
              followOperation(user.userId, user.followEachOther === 0);
            }
          "
        />
      </div>
    </ion-content>
  </ion-page>
</template>
